            else {
                X_value = 10;
                possibilities *= (i == 0) ? 9 : 10;
            }
        }
    }
    return possibilities;
}

int getDigit(const std::vector<char>& arr, int pos) {
    if (arr[pos] == '_' || arr[pos] == 'X') return -1;
    return arr[pos] - '0';
